bool flipCase( uvec2 v )
{
    while (v.x > 1u || v.y > 1u) v >>= 2u;
    return v != uvec2(0, 0);
}

uint roundDown( uint x )
{
    while ((x & x-1u) > 0u) x &= x-1u;
    return x;
}

uvec2 flipIf( bool c, uvec2 v )
{
	return c ? v.yx : v.xy;
}

// [0, inf) × [0, inf) -> [0, inf)
uint hilbert( uvec2 v )
{
    uint result = 0u;
    while (v != uvec2(0, 0)) {
        bool c = flipCase(v);
        uint s = max(roundDown(v.x), roundDown(v.y));
        uint S = 2u*s;
        bvec2 q = bvec2(v.x >= s, v.y >= s);

        uint quadrant = 0u;
        if (!q.x &&  q.y) quadrant = c? 3u: 1u;
        if ( q.x &&  q.y) quadrant = c? 2u: 2u;
        if ( q.x && !q.y) quadrant = c? 1u: 3u;

        /**/ if (quadrant == 1u) v =  v.yx - flipIf(c, uvec2(s   , 0u  ));
        else if (quadrant == 2u) v =  v.yx - flipIf(c, uvec2(s   , s   ));
        else if (quadrant == 3u) v = -v.xy + flipIf(c, uvec2(S-1u, s-1u));

        result += s*s * quadrant;
    }
    return result;
}

float blink( float t ) {
    return t < 0.0 ? 0.0 : exp(-0.05*t);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float scale = max(32.0/iResolution.x, 32.0/iResolution.y);
    vec2 uv = scale*(fragCoord - 0.5*iResolution.xy) + vec2(16.0);

    float t = mod(45.0 * iTime, 1024.0);
    uvec2 xy = uvec2(uv);

    vec3 col = vec3(0, 0, 0);
    if (0.0 <= uv.x&&uv.x <= 32.0 && 0.0 <= uv.y&&uv.y <= 32.0) {
        uint h = hilbert(xy);
        col = vec3(blink(t-float(h)));
        if (flipCase(xy)) col += vec3(.3, .0, .0);
    }

    fragColor = vec4(col, 1.0);
}
